 \"description\": \"X轴与Y轴的化学反应强度符号\"\n        },\n        \"tension_stars\": {\n          \"type\": \"integer\",\n          \"minimum\": 1,\n          \"maximum\": 5,\n          \"description\": \"故事张力指数（1-5星）\"\n        },\n        \"forbidden_elements\": {\n          \"type\": \"array\",\n          \"description\": \"避雷红线（创作禁忌元素）\",\n          \"items\": {\n            \"type\": \"string\"\n          },\n          \"minItems\": 1\n        },\n        \"x_axis_display\": {\n          \"type\": \"string\",\n          \"description\": \"X轴模式在故事中的具体显影方式\"\n        },\n        \"y_axis_combination_effect\": {\n          \"type\": \"string\",\n          \"description\": \"Y轴标签组合产生的效应描述\"\n        },\n        \"reaction_formula\": {\n          \"type\": \"string\",\n          \"description\": \"化学反应公式的一句话描述\"\n        },\n        \"platform_fit\": {\n          \"type\": \"array\",\n          \"description\": \"适合发布的平台类型\",\n          \"items\": {\n            \"type\": \"string\"\n          }\n        }\n      }\n    },\n    \"one_sentence_synopsis\": {\n      \"type\": \"string\",\n      \"description\": \"一句话故事梗概（30-50字）\",\n      \"minLength\": 30,\n      \"maxLength\": 50\n    }\n  }\n}\n","size":4455}"}], "structuredContent": {"status": "success", "path": "data_pools/schemas/creative_intent.schema.json", "content": "{
  "$schema": "http://json-schema.org/draft-07/schema#",
