[{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陈志远",
      "role": "protagonist",
      "identity": "倒爷（个体户）",
      "traits": ["果断", "深情", "绝望", "责任感强", "时代感"],
      "overt_motivation": "完成这单跨省生意，赚到钱娶她",
      "covert_motivation": "用生命证明自己的爱，即使失败也要给她自由",
      "secret_fear": "害怕拖累她，让她跟着自己受苦",
      "misperception_of_other": "以为她只是把他当作雇主，不知道她也在默默关注他",
      "hidden_connection": "在她下岗前就注意到了她，这次雇佣是有预谋的求婚"
    },
    {
      "name": "林秀云",
      "role": "deuteragonist",
      "identity": "国营厂下岗女工",
      "traits": ["坚韧", "温柔", "敏感", "务实", "有希望"],
      "overt_motivation": "找到一份工作，重新开始生活",
      "covert_motivation": "渴望被爱，但不敢相信爱情",
      "secret_fear": "害怕再次失去，无论是工作还是爱情",
      "misperception_of_other": "以为他只是需要一个押货的人，不知道这是他的求婚仪式",
      "hidden_connection": "每次经过城市都在地图上画心，记录他们的旅程"
    }
  ],
  "supporting_characters": [
    {
      "name": "老张",
      "function": "阻碍",
      "identity": "市场管理员",
      "description": "代表1992年各种'规则'的执行者，对倒爷进行刁难和罚款"
    },
    {
      "name": "小贩",
      "function": "助力",
      "identity": "路边摊主",
      "description": "在暴风雨中卖红丝巾给男主，见证了他们的温情时刻"
    }
  ],
  "relationship_dynamics": "表面是雇佣关系，实际是男主的'流浪婚礼'。双向暗恋让每一次互动都充满张力，但时代的残酷现实（商战权谋+规则怪谈）最终迫使男主选择牺牲自己成全她的未来。枕巾从商品变成聘礼再变成遗物，边斗从货仓变成婚房再变成棺材隐喻。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕：开篇（0-1500字）- 建立1992年时代背景，介绍主角和核心冲突，开始七天七夜的旅程",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "南方启程",
        "core_event": "陈志远骑着嘉陵摩托来到林秀云下岗的工厂，邀请她押货北上。她以为是普通雇佣，坐上后座开始了七天七夜的旅程。",
        "emotional_tone": "迷茫与希望交织",
        "key_scenes": [
          "工厂门口的告别",
          "第一次看到摩托车边斗里的枕巾",
          "穿越第一个县城，男主买枕巾"
        ]
      }
    ],
    "turning_point": "林秀云发现男主每到一个县城都要买一对鸳鸯枕巾，开始怀疑这不仅仅是生意"
  },
  "act_two": {
    "description": "第二幕：挣扎（1500-5000字）- 旅途中感情逐渐升温，但商业风险和时代规则不断施压，男主内心挣扎加剧",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "风雨同行",
        "core_event": "暴风雨中男主停车为她买红丝巾，两人在雨中相拥。林秀云偷偷在地图上画心，男主默默观察但不说破。",
        "emotional_tone": "温暖中的不安",
        "key_scenes": [
          "暴风雨中的红丝巾",
          "供销社买枕巾的温馨时刻",
          "夜晚露宿时的对话"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "规则之困",
        "core_event": "遇到市场管理员老张的刁难，货物被扣留罚款。男主用最后的钱疏通关系，生意前景变得黯淡。",
        "emotional_tone": "压抑与焦虑",
        "key_scenes": [
          "检查站的对峙",
          "男主深夜数钱的场景",
          "林秀云发现他偷偷吃干粮省钱"
        ]
      },
      {
        "chapter_number": 4,
        "chapter_title": "最后的交易",
        "core_event": "到达北方目的地，但市场行情突变，货物严重贬值。男主面临血本无归的现实，开始准备履行'死在路上'的承诺。",
        "emotional_tone": "绝望中的决绝",
        "key_scenes": [
          "市场交易失败",
          "男主独自在河边思考",
          "最后一次买枕巾"
        ]
      }
    ],
    "turning_point": "男主告诉林秀云真相：'如果这单赚了，我娶你；如果赔了，摩托归你，我归摩托（死在路上）'"
  },
  "act_three": {
    "description": "第三幕：高潮+结局（5000-8000字）- X-Y化学反应爆发，男主选择牺牲，悲剧结局",
    "key_chapters": [
      {
        "chapter_number": 5,
        "chapter_title": "一万张婚床",
        "core_event": "最后一夜在桥洞下过夜，男主把所有枕巾铺开当床，说'现在我们有一万张婚床'。两人终于坦诚相对，但男主已经决定离开。",
        "emotional_tone": "甜蜜中的绝望",
        "key_scenes": [
          "枕巾铺成的婚床",
          "男主讲述他的'流浪婚礼'计划",
          "林秀云的眼泪和拥抱"
        ]
      },
      {
        "chapter_number": 6,
        "chapter_title": "消失的爱人",
        "core_event": "清晨林秀云醒来，发现男主已经离开，只留下摩托车和一张纸条。她疯狂寻找，最终在河边发现他的遗物和枕巾。",
        "emotional_tone": "撕心裂肺的痛苦",
        "key_scenes": [
          "空荡荡的桥洞",
          "纸条上的告别信",
          "河边的最后发现"
        ]
      },
      {
        "chapter_number": 7,
        "chapter_title": "枕巾的归宿",
        "core_event": "林秀云卖掉摩托车，但不是去买深圳的车票，而是用钱在每个他们经过的城市买了一对枕巾，寄回给当地的孤儿院，完成男主未竟的心愿。",
        "emotional_tone": "绝望中的传承",
        "key_scenes": [
          "卖掉摩托车的决定",
          "寄出枕巾的过程",
          "最后一对枕巾留在桥洞"
        ]
      }
    ]
  }
}"}]

